// STEP 4 convert Conversion of data to an object
// Converts a NoteCreateRequest into a Note entity
package com.planetpulse.api.mapper;

import com.planetpulse.api.dto.request.NoteCreateRequest;
import com.planetpulse.api.entity.Note;
// converter
import org.mapstruct.Mapper;
// How to convert
import org.mapstruct.Mapping;

// Tells MapStruct to generate the mapper implementation
// and make it available as a Spring component.
@Mapper(componentModel = "spring")
public interface NoteMapper {

    // The technical timestamp is generated by NoteService,
    // MapStruct must not try to map it from the request.
    //@Mapping(target = "noteTimestamp", ignore = true)

    // The country is retrieved by NoteService using countryId,
    // MapStruct must not try to map it from the request.
    @Mapping(target = "country", ignore = true)

    // Converts the received request into a Note object.
    Note toEntity(NoteCreateRequest request);
}
